    "notes": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "### Continue the investigation\nUse the panel menu to open its resolved query in Search. Review **Shared switch inventory** for exact serial matches and **Reported topology** for endpoint/port evidence. Neither establishes a traffic path.\n\n**Optional expansion:** Search the library for ISE, Secure Firewall, SD-WAN, Meraki or ThousandEyes. Only link records when exact device, IP, session or test identities agree; review address reuse and scope first.",
        "backgroundColor": "transparent",
        "fontColor": "#ecf0f5"
      }
    },
    "viz_header_bg": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#1c2738",
        "strokeColor": "rgba(100,158,245,0.28)",
        "rx": 10
      }
    },
    "viz_header_icon": {
      "type": "splunk.image",
      "title": "DC Networking Operations",
      "options": {
        "preserveAspectRatio": true,
        "src": "/static/app/splunk-cisco-dashboards/images/nav-icons/ServersWrench.svg"
      }
    },
    "viz_header": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "# DC Networking Operations\nLab observations \u00b7 Start with attention, confirm coverage, then follow product evidence.",
        "backgroundColor": "transparent",
        "fontColor": "#ecf0f5"
      }
    },
    "viz_scope": {
      "type": "splunk.markdown",
      "title": "",
      "showLastUpdated": false,
      "showProgressBar": false,
      "options": {
        "backgroundColor": "transparent",
        "fontColor": "#a6adb6",
        "fontSize": "custom",
        "customFontSize": 15,
        "markdown": "The configured DC index macro and selected time window define this overview. Administrative enablement is not availability. Blank measurements are unknown. Shared timing does not prove cause."
      }
    },
    "card_viz_attention_history_background": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#131a23",
        "strokeColor": "rgba(100,158,245,0.28)",
        "rx": 12
