      "showProgressBar": false,
      "options": {
        "backgroundColor": "transparent",
        "fontColor": "#a6adb6",
        "fontSize": "custom",
        "customFontSize": 15,
        "markdown": "Latest observation per entity in each 15-minute bucket. Missing measurements stay unknown; this is observed history, not a complete snapshot."
      }
    },
    "search_attention_history": {
      "type": "splunk.cisco_drilldown_action",
      "options": {
        "action": "open-search",
